```python
def equiv(A: FiniteStateAutomaton, B: FiniteStateAutomaton, log=False) -> bool:
  W, V = {(ε_closure(A.I, A.δ), ε_closure(B.I, B.δ))}, set()  # work, visited
  while W != set():
    P, Q = W.pop()
    if (P, Q) not in V:
      if log:
        print('checking', P, Q)
      if (P & A.F == set()) != (Q & B.F == set()):
        return False
      for a in A.Σ | B.Σ:
        W |= {(ε_closure(δ̂(A.δ, P, a), A.δ), ε_closure(δ̂(B.δ, Q, a), B.δ))}
      V |= {(P, Q)}
  if log:
    print('equivalent', V)
  return True
```

